let state=JSON.parse(localStorage.getItem('nomadGame'))||{coins:1000000,materials:100,x:50,y:50,world:'earth',objects:[],floods:0,avatar:null,humanoid:null,wallet:{cash:100000,bank:900000},transactions:[]};let selected=null;const $=id=>document.getElementById(id);function save(){localStorage.setItem('nomadGame',JSON.stringify(state))}function say(t){$('message').textContent=t}function cost(t){return{module:50,farm:35,solar:30,road:20,canal:15}[t]}function label(t){return{module:'🏠 HABITAT',farm:'🌱 AGRICULTURE',solar:'☀️ ÉNERGIE',road:'🛣️ LIAISON',canal:'🌊 EAU'}[t]}function render(){ $('coins').textContent=state.coins.toLocaleString('fr-FR');$('cash').textContent=state.wallet.cash.toLocaleString('fr-FR');$('bank').textContent=state.wallet.bank.toLocaleString('fr-FR');$('materials').textContent=state.materials;$('player').style.left=state.x+'%';$('player').style.top=state.y+'%';$('pos').textContent=state.world.toUpperCase();$('avatarLabel').textContent=state.avatar?.name||'—';$('botLabel').textContent=state.humanoid?.name||'—';$('player').textContent=state.avatar?.symbol||'👤';$('player').className='avatar-player';document.querySelectorAll('.placed').forEach(e=>e.remove());state.objects.filter(o=>o.world===state.world).forEach(o=>{let e=document.createElement('div');e.className='placed '+o.type+(o.damaged?' damaged':'');e.textContent=label(o.type);e.style.left=o.x+'%';e.style.top=o.y+'%';$('terrain').appendChild(e)})}function spend(n){if(state.coins<n){say('🎙️ Petite voix : Votre compte est vide. La construction attendra.');return false}state.coins-=n;state.wallet.bank-=n;state.transactions.unshift({type:'depense',amount:n,label:'Construction'});return true}
function setupCreator(){let ac=[['👤 Explorateur','👤'],['🧑‍🔧 Bâtisseur','🧑‍🔧'],['🧑‍🔬 Chercheur','🧑‍🔬'],['🧑‍🌾 Cultivateur','🧑‍🌾']];let bc=[['🤖 Humanoïde polyvalent','🤖'],['🦾 Constructeur','🦾'],['🧑‍🚀 Explorateur','🧑‍🚀'],['🛠️ Technicien','🛠️']];$('avatarChoices').innerHTML=ac.map((x,i)=>'<button data-a="'+i+'">'+x[0]+'</button>').join('');$('botChoices').innerHTML=bc.map((x,i)=>'<button data-b="'+i+'">'+x[0]+'</button>').join('');let av=0,bo=0;document.querySelectorAll('[data-a]').forEach(b=>b.onclick=()=>{av=+b.dataset.a;document.querySelectorAll('[data-a]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected')});document.querySelectorAll('[data-b]').forEach(b=>b.onclick=()=>{bo=+b.dataset.b;document.querySelectorAll('[data-b]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected')});$('startGame').onclick=()=>{let n=$('avatarName').value.trim()||'Nomad';let h=$('botName').value.trim()||'Mon humanoïde';state.avatar={name:n,symbol:ac[av][1],style:ac[av][0]};state.humanoid={name:h,symbol:bc[bo][1],style:bc[bo][0]};save();$('creation').style.display='none';say('🚀 Bienvenue '+n+' ! '+h+' vous accompagne. Vous disposez de 1 000 000 NOMAD.');render()}}if(!state.avatar||!state.humanoid)setupCreator();else $('creation').style.display='none';
document.querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>{selected=b.dataset.place;$('selection').textContent='Construction : '+label(selected)+' — touchez votre terrain.'});$('terrain').onclick=e=>{if(!selected||e.target!==$('terrain'))return;let r=$('terrain').getBoundingClientRect(),px=(e.clientX-r.left)/r.width*100,py=(e.clientY-r.top)/r.height*100;if(!spend(cost(selected)))return;state.objects.push({type:selected,x:Math.max(3,Math.min(92,px)),y:Math.max(3,Math.min(92,py)),world:state.world});say(label(selected)+' placé sur votre plateforme.');selected=null;$('selection').textContent='Aucune construction sélectionnée.';save();render()};function addMoney(n,labelTx){state.coins+=n;state.wallet.bank+=n;state.transactions.unshift({type:'gain',amount:n,label:labelTx})}function buyCash(n){if(state.wallet.bank<n){say('💸 Fonds bancaires insuffisants.');return}state.wallet.bank-=n;state.wallet.cash+=n;state.transactions.unshift({type:'retrait',amount:n,label:'Retrait fictif'});say('🏧 Retrait de '+n.toLocaleString('fr-FR')+' NOMAD.')}function depositCash(n){if(state.wallet.cash<n){say('💵 Espèces insuffisantes.');return}state.wallet.cash-=n;state.wallet.bank+=n;state.transactions.unshift({type:'depot',amount:n,label:'Dépôt fictif'});say('🏦 Dépôt de '+n.toLocaleString('fr-FR')+' NOMAD.')}function switchWorld(w){state.world=w;state.x=50;state.y=50;let info={earth:'🌍 Terre : ville NOMAD existante. Greffez votre plateforme ou partez construire ailleurs.',sea:'🌊 Mer : ville flottante NOMAD existante. Côte, haute mer et zones sous-marines.',space:'🛰️ Espace : ville orbitale NOMAD déjà habitée.',moon:'🌙 Lune : ville NOMAD déjà installée.',mars:'🔴 Mars : ville NOMAD déjà habitée.'};$('worldInfo').textContent=info[w];say('Vous arrivez dans '+w.toUpperCase()+'. Votre avatar et votre humanoïde vous accompagnent.');save();render()}$('earth').onclick=()=>switchWorld('earth');$('sea').onclick=()=>switchWorld('sea');$('space').onclick=()=>switchWorld('space');$('moon').onclick=()=>switchWorld('moon');$('mars').onclick=()=>switchWorld('mars');$('editAvatar').onclick=()=>{$('creation').style.display='grid';$('avatarName').value=state.avatar?.name||'';$('botName').value=state.humanoid?.name||''};$('rain').onclick=()=>{state.floods++;let d=0;state.objects=state.objects.map(o=>{if(o.world==='earth'&&(o.type==='module'||o.type==='farm')&&o.x>68&&Math.random()<.75){d++;return{...o,damaged:true}}return o});say(d?'🌧️ Inondation ! '+d+' construction(s) endommagée(s).':'🌧️ Forte pluie. Votre plateforme tient bon.');save();render()};$('storm').onclick=()=>{let t=state.objects.filter(o=>o.world==='sea');let d=t.length&&Math.random()<.6?t[Math.floor(Math.random()*t.length)]:null;if(d)d.damaged=true;say(d?'🌊 Tempête : une installation est endommagée.':'🌊 Tempête : la ville NOMAD résiste.');save();render()};$('spaceEvent').onclick=()=>{say(Math.random()<.5?'☄️ Micrométéorite : réparation nécessaire.':'🛰️ Incident technique : maintenance en cours.');if(state.materials>=10)state.materials-=10;save();render()};$('moonEvent').onclick=()=>{say('🌙 Alerte lunaire : poussière et environnement hostile. Sécurisation en cours.');save();render()};$('marsEvent').onclick=()=>{say(Math.random()<.5?'🔴 Tempête de poussière martienne : énergie perturbée.':'🔴 Incident de ressource : production réorganisée.');if(state.materials>=10)state.materials-=10;save();render()};$('parkGame').onclick=()=>{addMoney(15,'Activité');say('🎯 Activité réussie : +15 NOMAD.');save();render()};$('workGame').onclick=()=>{if(state.materials>=10){state.materials-=10;addMoney(10,'Production');say('🏭 Production réussie : +10 NOMAD.')}else say('Plus assez de matériaux.');save();render()};$('withdraw').onclick=()=>{let n=Number($('cashAmount').value)||0;if(n>0)buyCash(n);save();render()};$('deposit').onclick=()=>{let n=Number($('cashAmount').value)||0;if(n>0)depositCash(n);save();render()};$('save').onclick=()=>{save();say('💾 Sauvegarde locale effectuée.')};$('reset').onclick=()=>{if(confirm('Réinitialiser la partie locale ?')){localStorage.removeItem('nomadGame');location.reload()}};$('voice').onclick=()=>say('🎙️ Petite voix : Je vous observe. Je ne décide pas à votre place.');document.addEventListener('keydown',e=>move(e.key));document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>move({left:'ArrowLeft',right:'ArrowRight',up:'ArrowUp',down:'ArrowDown'}[b.dataset.move]));function move(k){let s=4;if(k==='ArrowLeft')state.x=Math.max(2,state.x-s);if(k==='ArrowRight')state.x=Math.min(98,state.x+s);if(k==='ArrowUp')state.y=Math.max(2,state.y-s);if(k==='ArrowDown')state.y=Math.min(98,state.y+s);save();render()}if(!state.wallet){state.wallet={cash:100000,bank:state.coins};state.coins=state.wallet.bank}render();